package android.graphics;
public class Paint {
 public static final int ANTI_ALIAS_FLAG=1;
 public enum Join { MITER, ROUND, BEVEL } public enum Style { FILL, STROKE, FILL_AND_STROKE } public enum Align { LEFT, CENTER, RIGHT } public enum Cap { BUTT, ROUND, SQUARE }
 private int color=0xff000000; private Style style=Style.FILL; private Align align=Align.LEFT; private Cap cap=Cap.BUTT;
 private float strokeWidth=0, textSize=16, letterSpacing, textScale=1, textSkew, miter=4; private int flags; private String features; private Shader shader; private ColorFilter filter; private Xfermode xfer; private PathEffect effect; private Join join=Join.MITER; private boolean aa; private Typeface typeface;
 public Paint() {} public Paint(int flags) { this.flags=flags; aa=(flags & ANTI_ALIAS_FLAG)!=0; } public Paint(Paint p) { set(p); }
 public void setColor(int c) { color=c; } public int getColor() { return color; } public int indroidColor() { return filter instanceof PorterDuffColorFilter ? ((PorterDuffColorFilter)filter).color : shader!=null ? shader.color : color; }
 public void setARGB(int a,int r,int g,int b) { color=Color.argb(a,r,g,b); }
 public void setAlpha(int a) { color=(color & 0xffffff) | ((a & 255)<<24); } public int getAlpha() { return color >>> 24; }
 public void setStyle(Style s) { style=s; } public Style getStyle() { return style; }
 public void setStrokeWidth(float w) { strokeWidth=w; } public float getStrokeWidth() { return strokeWidth; }
 public void setStrokeCap(Cap c) { cap=c; } public Cap getStrokeCap() { return cap; }
 public void setTextSize(float s) { textSize=s; } public float getTextSize() { return textSize; }
 public void setTextAlign(Align a) { align=a; } public Align getTextAlign() { return align; }
 public void setAntiAlias(boolean a) { aa=a; } public boolean isAntiAlias() { return aa; }
 public Typeface setTypeface(Typeface t) { typeface=t; return t; } public Typeface getTypeface() { return typeface; }
 public float measureText(String s) { return measureText(s,0,s.length()); }
 public float measureText(String s,int start,int end) { float n=0; for(int i=start;i<end;i++) { char c=s.charAt(i); n+= c==' ' ? .28f : c>='0' && c<='9' ? .56f : c=='i' || c=='l' || c=='I' || c=='!' || c=='.' || c==',' ? .3f : .55f; } return (n+Math.max(0,end-start-1)*letterSpacing)*textSize*textScale; }
 public void getTextBounds(String s,int start,int end,Rect r) { r.set(0,(int)(-textSize*.8f),(int)measureText(s,start,end),(int)(textSize*.2f)); }
 public static class FontMetrics { public float top,ascent,descent,bottom,leading; }
 public FontMetrics getFontMetrics() { FontMetrics f=new FontMetrics(); getFontMetrics(f); return f; }
 public float getFontMetrics(FontMetrics f) { f.top=-1.06f*textSize; f.ascent=-.928f*textSize; f.descent=.244f*textSize; f.bottom=.27f*textSize; f.leading=0; return f.descent-f.ascent; }
 public float ascent() { return -.928f*textSize; } public float descent() { return .244f*textSize; }
 public static class FontMetricsInt { public int top,ascent,descent,bottom,leading; }
 public FontMetricsInt getFontMetricsInt(){FontMetricsInt f=new FontMetricsInt();getFontMetricsInt(f);return f;} public int getFontMetricsInt(FontMetricsInt f){int top=(int)Math.floor(-1.06f*textSize),ascent=(int)Math.floor(-.928f*textSize),descent=(int)Math.ceil(.244f*textSize),bottom=(int)Math.ceil(.27f*textSize);if(f!=null){f.top=top;f.ascent=ascent;f.descent=descent;f.bottom=bottom;f.leading=0;}return descent-ascent;}
 public void set(Paint p){color=p.color;style=p.style;align=p.align;cap=p.cap;strokeWidth=p.strokeWidth;textSize=p.textSize;aa=p.aa;typeface=p.typeface;flags=p.flags;shader=p.shader;filter=p.filter;xfer=p.xfer;effect=p.effect;letterSpacing=p.letterSpacing;textScale=p.textScale;textSkew=p.textSkew;join=p.join;miter=p.miter;features=p.features;} public void reset(){set(new Paint());} public int getFlags(){return flags;} public void setFlags(int f){flags=f;aa=(f&1)!=0;} public Shader setShader(Shader s){Shader old=shader;shader=s;return old;} public Shader getShader(){return shader;} public ColorFilter setColorFilter(ColorFilter f){ColorFilter old=filter;filter=f;return old;} public ColorFilter getColorFilter(){return filter;} public Xfermode setXfermode(Xfermode x){Xfermode old=xfer;xfer=x;return old;} public Xfermode getXfermode(){return xfer;} public PathEffect setPathEffect(PathEffect p){PathEffect old=effect;effect=p;return old;} public PathEffect getPathEffect(){return effect;} public void setStrokeJoin(Join j){join=j;} public Join getStrokeJoin(){return join;} public void setStrokeMiter(float m){miter=m;} public float getStrokeMiter(){return miter;} public void setLetterSpacing(float v){letterSpacing=v;} public float getLetterSpacing(){return letterSpacing;} public void setTextScaleX(float v){textScale=v;} public float getTextScaleX(){return textScale;} public void setTextSkewX(float v){textSkew=v;} public float getTextSkewX(){return textSkew;} public void setFakeBoldText(boolean b){} public void setFilterBitmap(boolean b){} public void setLinearText(boolean b){} public void setShadowLayer(float radius,float dx,float dy,int color){} public void clearShadowLayer(){} public boolean hasGlyph(String s){return s!=null&&s.length()>0;} public boolean isElegantTextHeight(){return false;} public String getFontFeatureSettings(){return features;} public void setFontFeatureSettings(String s){features=s;} public float measureText(CharSequence s,int start,int end){return measureText(s.toString(),start,end);} public float measureText(char[] s,int index,int count){return measureText(new String(s,index,count));} public int breakText(String text,boolean forwards,float maxWidth,float[] measured){int count=0;float width=0;for(int i=0;i<text.length();i++){int at=forwards?i:text.length()-1-i;float next=measureText(text,at,at+1)+(count==0?0:letterSpacing*textSize);if(width+next>maxWidth)break;width+=next;count++;}if(measured!=null&&measured.length>0)measured[0]=width;return count;} public int breakText(CharSequence s,int start,int end,boolean forwards,float width,float[] measured){return breakText(s.subSequence(start,end).toString(),forwards,width,measured);} public int breakText(char[] s,int index,int count,float width,float[] measured){return breakText(new String(s,index,count<0?-count:count),count>=0,width,measured);} public void getTextBounds(char[] s,int index,int count,Rect r){getTextBounds(new String(s,index,count),0,count,r);}
 public android.os.LocaleList getTextLocales() { return android.os.LocaleList.getDefault(); }
}
